CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE member_role AS ENUM ('OWNER','ADMIN','EDITOR','VIEWER');
CREATE TYPE media_kind AS ENUM ('IMAGE','CAROUSEL','REEL');
CREATE TYPE publish_status AS ENUM ('QUEUED','PROCESSING','PUBLISHED','FAILED','NEEDS_VERIFICATION','UNCERTAIN','CANCELLED');
CREATE TYPE task_kind AS ENUM ('AUTHENTICATE','PUBLISH','METRICS');

CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, role member_role NOT NULL DEFAULT 'EDITOR', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (organization_id,user_id));
CREATE TABLE instagram_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, username text NOT NULL, display_name text, avatar_url text, state text NOT NULL DEFAULT 'DISCONNECTED', last_authenticated_at timestamptz, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,username));
CREATE INDEX instagram_accounts_org_idx ON instagram_accounts(organization_id);
CREATE TABLE account_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,name));
CREATE TABLE account_group_members (group_id uuid NOT NULL REFERENCES account_groups ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES instagram_accounts ON DELETE CASCADE, PRIMARY KEY(group_id,account_id));
CREATE TABLE encrypted_secrets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL UNIQUE REFERENCES instagram_accounts ON DELETE CASCADE, credential_ciphertext bytea, session_ciphertext bytea, encryption_key_version text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, object_key text NOT NULL, mime_type text NOT NULL, bytes bigint NOT NULL, width int, height int, duration_seconds numeric, kind media_kind NOT NULL, created_by uuid REFERENCES users ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publication_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, created_by uuid REFERENCES users ON DELETE SET NULL, label text, scheduled_at timestamptz, paused_at timestamptz, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,idempotency_key));
CREATE TABLE account_publications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, batch_id uuid NOT NULL REFERENCES publication_batches ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES instagram_accounts ON DELETE CASCADE, media_id uuid NOT NULL REFERENCES media ON DELETE RESTRICT, kind media_kind NOT NULL, caption text NOT NULL DEFAULT '', share_to_feed boolean NOT NULL DEFAULT false, scheduled_at timestamptz, status publish_status NOT NULL DEFAULT 'QUEUED', attempts int NOT NULL DEFAULT 0, error_message text, final_url text, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,batch_id,account_id));
CREATE INDEX account_publications_org_created_idx ON account_publications(organization_id,created_at DESC);
CREATE INDEX account_publications_queue_idx ON account_publications(status,scheduled_at);
CREATE TABLE execution_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), publication_id uuid NOT NULL REFERENCES account_publications ON DELETE CASCADE, attempt_number int NOT NULL, started_at timestamptz, finished_at timestamptz, outcome text, error_code text, error_message text, duration_ms int, peak_rss_bytes bigint, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(publication_id,attempt_number));
CREATE TABLE intervention_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES instagram_accounts ON DELETE CASCADE, publication_id uuid REFERENCES account_publications ON DELETE SET NULL, kind text NOT NULL, status text NOT NULL DEFAULT 'OPEN', safe_summary text NOT NULL, screenshot_key text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours', resolved_at timestamptz);
CREATE TABLE metric_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES instagram_accounts ON DELETE CASCADE, publication_id uuid REFERENCES account_publications ON DELETE CASCADE, metric_name text NOT NULL, metric_definition text NOT NULL, metric_value bigint, observed_at timestamptz NOT NULL, source text NOT NULL, quality text NOT NULL DEFAULT 'OBSERVED', UNIQUE(account_id,publication_id,metric_name,observed_at));
CREATE INDEX metric_snapshots_observed_idx ON metric_snapshots(organization_id,observed_at);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE, actor_user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, target_type text NOT NULL, target_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
